import '../services/auth_service.dart';

class RegisterScreen extends StatefulWidget { const RegisterScreen({super.key}); @override State<RegisterScreen> createState()=>_RegisterScreenState(); }
class _RegisterScreenState extends State<RegisterScreen> {
 final keyForm=GlobalKey<FormState>(); final name=TextEditingController(),email=TextEditingController(),pass=TextEditingController(),confirm=TextEditingController(); final auth=AuthService(); bool busy=false,accepted=false,hide=true;
