 String? required_(String? v)=>v==null||v.trim().isEmpty?'Campo obligatorio':null;
 InputDecoration dec(String h,IconData i)=>InputDecoration(hintText:h,prefixIcon:Icon(i),filled:true,fillColor:Colors.white,contentPadding:const EdgeInsets.symmetric(horizontal:20,vertical:19),border:OutlineInputBorder(borderRadius:BorderRadius.circular(36),borderSide:const BorderSide(color:Color(0xFFBECAB9))),enabledBorder:OutlineInputBorder(borderRadius:BorderRadius.circular(36),borderSide:const BorderSide(color:Color(0xFFBECAB9))));
