 Future<void> create() async {if(!keyForm.currentState!.validate())return;if(!accepted){msg('Acepta los términos y la política de privacidad.');return;}setState(()=>busy=true);try{await auth.signUp(email.text,pass.text,name:name.text);if(mounted){msg('Cuenta creada. Revisa tu correo para confirmar.');Navigator.pop(context);}}catch(_){if(mounted)msg('No se pudo crear la cuenta. Inténtalo nuevamente.');}finally{if(mounted)setState(()=>busy=false);}}
